        if (waitingTime != null) 'waitingTime': waitingTime!,
      };
}

/// One walk or ride.
class Leg {
  final LegTime start;
  final LegTime end;
  final Place from;
  final Place to;
  final Mode? mode;

  /// Seconds of delay applied to this leg's arrival at the requested `reliability`: that trip's typical delay at the stop on the service date's day type, from the environment's realtime history. Null when `reliability` is omitted or there is no history.
  final int? typicalArrivalDelay;
  final RealtimeState? realtimeState;

  /// True when the leg's times include realtime.
  final bool? realTime;

  /// The GTFS service date of the leg's trip, `YYYY-MM-DD`; null on a walk leg.
  final String? serviceDate;

  /// Null on a walk leg.
  final Route? route;
  final String? headsign;

  /// Metres.
  final double? distance;

  /// Seconds.
  final double? duration;

  /// Null on a walk leg.
  final Trip? trip;

  /// True on a transit leg ridden in the same vehicle as the previous leg: the vehicle carries on as another trip, often under another line number, and the rider stays on board. That change is not counted in `numberOfTransfers`. False on every other leg.
  final bool? interlineWithPreviousLeg;
  final Geometry? legGeometry;

  const Leg({
    required this.start,
    required this.end,
    required this.from,
    required this.to,
    this.mode,
    this.typicalArrivalDelay,
    this.realtimeState,
    this.realTime,
    this.serviceDate,
    this.route,
    this.headsign,
    this.distance,
    this.duration,
    this.trip,
    this.interlineWithPreviousLeg,
    this.legGeometry,
  });

  factory Leg.fromJson(Map<String, dynamic> json) => Leg(
        start: LegTime.fromJson(json['start'] as Map<String, dynamic>),
        end: LegTime.fromJson(json['end'] as Map<String, dynamic>),
        from: Place.fromJson(json['from'] as Map<String, dynamic>),
        to: Place.fromJson(json['to'] as Map<String, dynamic>),
        mode:
            json['mode'] == null ? null : Mode.fromWire(json['mode'] as String),
        typicalArrivalDelay: (json['typicalArrivalDelay'] as num?)?.toInt(),
        realtimeState: json['realtimeState'] == null
            ? null
            : RealtimeState.fromWire(json['realtimeState'] as String),
        realTime: json['realTime'] as bool?,
        serviceDate: json['serviceDate'] as String?,
        route: json['route'] == null
            ? null
            : Route.fromJson(json['route'] as Map<String, dynamic>),
        headsign: json['headsign'] as String?,
        distance: (json['distance'] as num?)?.toDouble(),
        duration: (json['duration'] as num?)?.toDouble(),
        trip: json['trip'] == null
            ? null
            : Trip.fromJson(json['trip'] as Map<String, dynamic>),
        interlineWithPreviousLeg: json['interlineWithPreviousLeg'] as bool?,
        legGeometry: json['legGeometry'] == null
            ? null
            : Geometry.fromJson(json['legGeometry'] as Map<String, dynamic>),
      );

  Map<String, dynamic> toJson() => {
        'start': start.toJson(),
        'end': end.toJson(),
        'from': from.toJson(),
        'to': to.toJson(),
        if (mode != null) 'mode': mode!.toJson(),
        if (typicalArrivalDelay != null)
          'typicalArrivalDelay': typicalArrivalDelay!,
        if (realtimeState != null) 'realtimeState': realtimeState!.toJson(),
        if (realTime != null) 'realTime': realTime!,
        if (serviceDate != null) 'serviceDate': serviceDate!,
        if (route != null) 'route': route!.toJson(),
        if (headsign != null) 'headsign': headsign!,
        if (distance != null) 'distance': distance!,
        if (duration != null) 'duration': duration!,
        if (trip != null) 'trip': trip!.toJson(),
        if (interlineWithPreviousLeg != null)
