/// Progress, with the itineraries that became final since the previous `chunk`.
class PlanStreamChunkEvent {
  /// Seconds of the window searched so far.
  final int frontier;

  /// Itineraries found so far.
  final int found;

  /// Itineraries sent so far, this chunk's included.
  final int finalized;

  /// Itineraries that became final with this chunk.
  final List<Itinerary> results;

  const PlanStreamChunkEvent({
    required this.frontier,
    required this.found,
    required this.finalized,
    required this.results,
  });

  factory PlanStreamChunkEvent.fromJson(Map<String, dynamic> json) =>
      PlanStreamChunkEvent(
        frontier: (json['frontier'] as num).toInt(),
        found: (json['found'] as num).toInt(),
        finalized: (json['finalized'] as num).toInt(),
        results: (json['results'] as List<dynamic>)
            .map((e) => Itinerary.fromJson(e as Map<String, dynamic>))
            .toList(),
      );

  Map<String, dynamic> toJson() => {
        'frontier': frontier,
        'found': found,
        'finalized': finalized,
        'results': results.map((e) => e.toJson()).toList(),
      };
}

/// Sent once, after the last `chunk`. To continue, send `endCursor` as `after` or `startCursor` as `before` in a new request.
class PlanStreamPageInfoEvent {
  final bool hasNextPage;
  final bool hasPreviousPage;

  /// Why the plan was declined; empty when it was not.
  final List<RoutingError> routingErrors;

  /// Send as `before` for earlier itineraries; null when there is none.
  final String? startCursor;

  /// Send as `after` for later itineraries; null when there is none.
  final String? endCursor;

  /// The window the stream searched, as an ISO-8601 duration; null for a declined plan.
  final String? searchWindowUsed;

  const PlanStreamPageInfoEvent({
    required this.hasNextPage,
    required this.hasPreviousPage,
    required this.routingErrors,
    this.startCursor,
    this.endCursor,
    this.searchWindowUsed,
  });

  factory PlanStreamPageInfoEvent.fromJson(Map<String, dynamic> json) =>
      PlanStreamPageInfoEvent(
        hasNextPage: json['hasNextPage'] as bool,
        hasPreviousPage: json['hasPreviousPage'] as bool,
        routingErrors: (json['routingErrors'] as List<dynamic>)
            .map((e) => RoutingError.fromJson(e as Map<String, dynamic>))
            .toList(),
        startCursor: json['startCursor'] as String?,
        endCursor: json['endCursor'] as String?,
        searchWindowUsed: json['searchWindowUsed'] as String?,
      );

  Map<String, dynamic> toJson() => {
        'hasNextPage': hasNextPage,
        'hasPreviousPage': hasPreviousPage,
        'routingErrors': routingErrors.map((e) => e.toJson()).toList(),
        if (startCursor != null) 'startCursor': startCursor!,
        if (endCursor != null) 'endCursor': endCursor!,
        if (searchWindowUsed != null) 'searchWindowUsed': searchWindowUsed!,
      };
}

/// The search work this stream used; ends the stream. `stoppedBy` is `targetResults` (enough itineraries sent), `maxWindow` (the whole window searched) or `rejected` (a declined plan); new values may be added.
class PlanStreamDoneEvent {
  /// Search iterations used.
  final int iterations;

  /// Seconds of the window searched.
  final int windowSeconds;

  /// Itineraries sent.
  final int resultCount;

  /// Why the stream stopped.
  final String stoppedBy;

  const PlanStreamDoneEvent({
    required this.iterations,
    required this.windowSeconds,
    required this.resultCount,
    required this.stoppedBy,
  });

  factory PlanStreamDoneEvent.fromJson(Map<String, dynamic> json) =>
      PlanStreamDoneEvent(
        iterations: (json['iterations'] as num).toInt(),
        windowSeconds: (json['windowSeconds'] as num).toInt(),
        resultCount: (json['resultCount'] as num).toInt(),
        stoppedBy: json['stoppedBy'] as String,
      );

  Map<String, dynamic> toJson() => {
        'iterations': iterations,
        'windowSeconds': windowSeconds,
        'resultCount': resultCount,
        'stoppedBy': stoppedBy,
      };
}

